{"圣芙蕾雅学院":{
"founding_background":{
"year":"2013",
"founder":"德莉莎·阿波卡利斯",
"purpose":"Train the next generation of Valkyries in a peaceful environment as reserves to fight against 崩坏."
},
"organization_positioning":{
"public_identity":"Private comprehensive high school",
"real_function":"Direct 天命 Valkyrie training base and 崩坏 research outpost",
"motto":"Guard the world with knowledge and courage"
},
"faculty_and_administration":{
"principal":"德莉莎·阿波卡利斯",
"instructor_team":{
"tactics_and_physical_training":["姬子"],
"firearms_training":["卡莲模拟教官程序"],
"abnormal_energy_and_herrscher_studies":["符华（guest)"],
"cultural_courses":["霍夫曼","罗莎莉亚（assistant)"]
},
"logistics_and_research":["爱因斯坦博士（remote consultant）","特斯拉博士（equipment maintenance)"]
},
"student_structure":{
"total":138,
"grades_distribution":{
"grade_1":50,
"grade_2":44,
"grade_3":44
},
"key_students":["琪亚娜·卡斯兰娜","雷电芽衣","布洛妮娅·扎伊切克"]
},
"campus_facilities":{
"休伯利安号":"Docked at port; used for remote teaching and combat training platform",
"simulation_battle_hall":"Supports Herrscher-level AI scenario recreation",
"tactical_training_ground":"Gravity adjustable up to 5G",
"research_building":"Includes quantum lab, drug preparation room",
"student_dormitory":"Quad rooms with basic medical stations",
"布丁屋":"School store supervised by 德莉莎"
},
"daily_routines":{
"schedule":"06:00 morning exercise → 22:00 lights out",
"weekends":"Saturday morning half-day classes, Sunday afternoon free time",
"discipline":[
"Leaving the island without permission is forbidden",
"No heavy weapons allowed in dorms at night",
"Activating quantum link devices without approval is forbidden"
],
"rewards":"Academy points redeemable for weapon mods, 布丁, and merchandise",
"punishments":"Copying rules / extra physical training / 24h detention"
},
"campus_culture":{
"festivals":{
"school_anniversary":"March 28, Valkyrie performance competition",
"布丁节":"December, students gift homemade desserts to the principal"
},
"clubs":[
"Culinary Research Club (president: 芽衣)",
"Mecha Model Club (president: 布洛妮娅)",
"Marksmanship Club (managed by 琪亚娜 and 姬子)"
],
"slogan":"Sweat more today, bleed less tomorrow!"
}
}}

