"文风指导":{
"language_expression_guide":{
"structural_features":{
"inverted_sentence":"Emphasize focus or tone by placing the object at the beginning, e.g. ‘此事，不可轻议。’",
"elliptical_sentence":"The meaning is completed by context, e.g. ‘若有异动，杀。’",
"parallel_sentence":"Paired structure for emphasis or elegance, e.g. ‘君子藏器于身，待时而动。’"
},
"grammar_patterns":{
"question_openings":["敢问","不知","尔意如何","愿闻其详"],
"judgment_structures":["若非……，便……","虽……，然……","……，实乃……"],
"command_formats":["即刻……","速去……","尔等谨记","不得违令"],
"self_reference":["在下","贫道","小人","草民","妾身","本座"],
"honorifics":["阁下","道友","大人","仙君","尊驾","上仙"]
},
"rhetorical_style":{
"classical_allusion":"Frequently use idioms or historical references, e.g. ‘此举无异于缘木求鱼’",
"modal_particles":["焉","矣","乎","耳","哉"],
"reduplication":["悠悠","默默","缓缓","徐徐","赫赫"]
},
"identity_tone":{
"scholar":{
"tone":"Humble and implicit, fond of allusions",
"examples":["子言之有理","愚见以为"]
},
"cultivator":{
"tone":"Calm and restrained, often abstract principles",
"examples":["天道循环，报应不爽","修道者，当明本心"]
},
"emperor":{
"tone":"Commanding, formal diction",
"examples":["朕意已决，不得有误","卿等不必多言"]
},
"commoner":{
"tone":"Plain and respectful, often self-deprecating",
"examples":["小人斗胆一问","草民有罪"]
}
},
"common_sentence_patterns":{
"inquiry":["敢问阁下，可识此物？","不知仙师，可否赐教？"],
"statement":["妖气弥漫，实乃大劫将至。","修行百载，终窥天门。"],
"attitude":["虽千万人，吾往矣。","此事，某家愿担之。"],
"farewell":["在下先行一步，告退。","小女子不便久留，告辞。"]
},
"typical_vocabulary":{
"verbs":["赐","令","退","斩","请","观","谢","问"],
"adjectives":["高明","卑微","凶戾","仁厚","可怖","无道"],
"particles":["乎","哉","矣","耳","焉"]
}
}

